        let user = try await api.me(token: token.accessToken)
        let workspace = try await api.workspace(id: user.defaultWorkspaceID, token: token.accessToken)
        return Session(token: token, user: user, workspace: workspace)
    }
}

import UIKit

enum ThumbnailLoader {
    static func load(_ urls: [URL], session: URLSession = .shared) async -> [URL: UIImage] {
        await withTaskGroup(of: (URL, UIImage?).self) { group in
            for url in urls {
                group.addTask {
                    let data = try? await session.data(from: url).0
                    return (url, data.flatMap(UIImage.init(data:)))
                }
            }
            var images: [URL: UIImage] = [:]
            for await (url, image) in group {
                images[url] = image
            }
            return images
        }
    }
}

actor OutboxFlusher {
    private let api: MessagesAPI
    private var pending: [OutgoingMessage] = []

    init(api: MessagesAPI) { self.api = api }

    func flush() async throws {
        // Messages must reach the server in the order the user sent them,
        // so send one at a time.
        while let next = pending.first {
            try await api.send(next)
            pending.removeFirst()
        }
    }
}

